L000755	\section{Spin Chirality and $\mathcal{R}$} \label{chiralityratio}
L000756	
L000757	Given three sites $i,j,k$, we define the spin chirality (with $\varepsilon_{xyz}=\varepsilon_{yzx}=\varepsilon_{zxy}=+1$) as
L000758	\begin{align}
L000759		\chi_{ijk} &= \langle \vec S_i \cdot (\vec S_j \times \vec S_k) \rangle = \epsilon^{\alpha \beta \gamma} \langle S^\alpha_i S^\beta_j S^\gamma_k \rangle = \langle (S_i^x S_j^y - S^y_i S^x_j) S^z_k \rangle + \langle S^y_i S^z_j S^x_k - S^x_i S^z_j S^y_k \rangle + \langle S^z_i (S^x_j S^y_k - S^y_j S^x_k) \rangle. \label{chirality_eq}
L000760	\end{align}
L000761	Using $S^x = (S^+ + S^-)/2$ and $S^y = -i (S^+ - S^-)/2$, we obtain the identity $S_i^x S_j^y - S^y_i S^x_j = i (S^+_i S^-_j - S^-_i S^+_j)/2$, which we use to evaluate $\chi_{ijk}$ in Eq.~\eqref{chirality_eq}, i.e. the numerator of  $\mathcal{R}$.
L000762	
L000763	The denominator of $\mathcal{R}$ is defined as the disconnected (one-point $\times$ two-point) contribution of Eq.~\eqref{chirality_eq}.
L000764	In our variational states $\langle S^\pm\rangle=0$, and the uniform longitudinal moment per site is $\langle S_i^z\rangle = \dfrac{(N_\uparrow-N_\downarrow)}{N} \dfrac{1}{2}=m/2$, which gives
L000765	\begin{align}
L000766		&\langle S_i^x S_j^y - S^y_i S^x_j\rangle\langle S^z_k \rangle + \langle S^y_i S^x_k - S^x_i S^y_k \rangle \langle  S^z_j\rangle  + \langle S^z_i \rangle \langle S^x_j S^y_k - S^y_j S^x_k \rangle \nonumber \\
L000767	    & = \frac{im}{4}  \Big(\big\langle S_j^+S_k^-\big\rangle-\big\langle S_j^-S_k^+\big\rangle + \big\langle S_k^+S_i^-\big\rangle-\big\langle S_k^-S_i^+\big\rangle + \big\langle S_i^+S_j^-\big\rangle-\big\langle S_i^-S_j^+\big\rangle\Big).
L000768	\end{align}
